var plugins = map[string]func() Plugin{}
var mu sync.RWMutex
func Register(name string, f func() Plugin) {
    mu.Lock()
    defer mu.Unlock()
    if _, dup := plugins[name]; dup { panic("duplicate driver: " + name) }
    plugins[name] = f
}
func Lookup(name string) (func() Plugin, bool) {
    mu.RLock()
    defer mu.RUnlock()
    return plugins[name]
}
